GRAMMAR_TOPICS=[_g(*x) for x in [["pronouns","Personal pronouns","Use common context-appropriate Thai pronouns.",["ผมเป็นนักเรียนครับ","คุณเป็นครูไหมครับ"]],["copula","Basic identity","Use เป็น and simple nominal patterns.",["ผมเป็นนักเรียนครับ","นี่บ้านของผม"]],["questions","Questions","Use ไหม and question words such as อะไร, ใคร, ที่ไหน.",["คุณเป็นนักเรียนไหมครับ","สถานีอยู่ที่ไหนครับ"]],["negation","Negation","Place ไม่ before common verbs and adjectives.",["ผมไม่กินกาแฟ","ผมไม่ยุ่งครับ"]],["classifiers","Classifiers","Count common people and objects.",["หนังสือสองเล่ม","นักเรียนสามคน"]],["location","Location","Use อยู่ and location phrases.",["ผมอยู่ที่บ้านครับ","หนังสืออยู่บนโต๊ะ"]],["politeness","Polite particles","Use ครับ and ค่ะ appropriately.",["ขอบคุณครับ","ขอบคุณค่ะ"]],["requests","Requests","Ask for repetition or practical help.",["กรุณาพูดอีกครั้งครับ","ช่วยผมหน่อยครับ"]]]]
